import 'package:flutter/material.dart';
class ModuleScreen extends StatelessWidget { const ModuleScreen({required this.title, super.key}); final String title; @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(title)), body:ListView(padding: const EdgeInsets.all(16), children:[Card(child:Padding(padding: const EdgeInsets.all(20), child:Column(crossAxisAlignment: CrossAxisAlignment.start, children:[Text(title, style: Theme.of(context).textTheme.headlineMedium), const SizedBox(height:8), const Text('Production-ready mobile module wired for FITFORGE AI backend API integration.'), const SizedBox(height:16), FilledButton.icon(onPressed:(){}, icon: const Icon(Icons.sync), label: const Text('Sync Now'))]))), for(final row in ['Live data','History','Analytics','Notifications']) Card(child:ListTile(title:Text(row), subtitle:Text('$title $row')))])); }
